import { createRequire } from "node:module";
import { readdirSync, readFileSync, writeFileSync, statSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { getIcons } from "@iconify/utils";

const require = createRequire(import.meta.url);
const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const srcDir = join(root, "src");
const outFile = join(root, "src", "lib", "icon-bundle.ts");
const attributionFile = join(root, "THIRD_PARTY_ICONS.md");

/** Icon sets we ship. A name with any other prefix is an error. */
const COLLECTIONS = [
  "solar", "pixel", "mdi", "simple-icons", "circle-flags", "ph",
  "material-symbols", "mingcute", "svg-spinners", "noto", "lucide",
  "line-md", "ic", "fluent", "eos-icons",
];

/** `prefix:name` shaped string literals that are not icons (tailwind variants, CSS values). */
const NOT_ICONS = new Set([
  "hover", "group-hover", "focus", "active", "data", "0",
  "visibility", "overflow",
]);

const ICON_RE = /["'`]([a-z][a-z0-9-]*):([a-z0-9][a-z0-9-]*)["'`]/g;

function walk(dir) {
  const out = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...walk(full));
    else if (/\.tsx?$/.test(full)) out.push(full);
  }
  return out;
}

const found = new Map(); // prefix -> Set<name>
const unknown = new Map(); // prefix -> Set<file>

for (const file of walk(srcDir)) {
  if (file === outFile) continue;
  const source = readFileSync(file, "utf8");
  for (const [, prefix, name] of source.matchAll(ICON_RE)) {
    if (NOT_ICONS.has(prefix)) continue;
    if (!COLLECTIONS.includes(prefix)) {
      if (!unknown.has(prefix)) unknown.set(prefix, new Set());
      unknown.get(prefix).add(relative(root, file));
      continue;
    }
    if (!found.has(prefix)) found.set(prefix, new Set());
    found.get(prefix).add(name);
  }
}

if (unknown.size > 0) {
  console.error("Unknown icon prefixes. Add the set to COLLECTIONS, or the string to NOT_ICONS:");
  for (const [prefix, files] of unknown) {
    console.error(`  ${prefix}:  ${[...files].slice(0, 3).join(", ")}`);
  }
  process.exit(1);
}

const chunks = [];
const used = []; // { prefix, name, count, author, license } for the attribution file
let total = 0;

for (const prefix of COLLECTIONS) {
  const names = [...(found.get(prefix) ?? [])].sort();
  if (names.length === 0) {
    console.warn(`  ${prefix}: unused, drop it from COLLECTIONS and package.json`);
    continue;
  }

  const collection = JSON.parse(
    readFileSync(require.resolve(`@iconify-json/${prefix}/icons.json`), "utf8"),
  );
  const subset = getIcons(collection, names);

  if (!subset || subset.not_found?.length) {
    console.error(`Icons missing from @iconify-json/${prefix}:`);
    for (const name of subset?.not_found ?? names) console.error(`  ${prefix}:${name}`);
    process.exit(1);
  }

  delete subset.not_found;
  delete subset.lastModified;
  total += names.length;
  chunks.push(`addCollection(${JSON.stringify(subset)});`);
  console.log(`  ${prefix}: ${names.length}`);

  const info = JSON.parse(
    readFileSync(require.resolve(`@iconify-json/${prefix}/info.json`), "utf8"),
  );
  used.push({ prefix, count: names.length, info });
}

const credits = used
  .map(({ prefix, count, info }) =>
    `//   ${prefix} (${count}) — ${info.name} by ${info.author?.name ?? "unknown"}, ${info.license?.title ?? "unknown licence"}`)
  .join("\n");

const banner = `// GENERATED by scripts/generate-icon-bundle.mjs — do not edit.
${credits}
import { addCollection } from "@iconify/react/dist/offline.js";

`;

writeFileSync(outFile, banner + chunks.join("\n") + "\n");

const attribution = `# Third-party icon artwork

The launcher bundles ${total} icons from the sets below. The artwork is redistributed
unmodified; only the icons actually used are included, extracted from the \`@iconify-json/*\`
packages by \`scripts/generate-icon-bundle.mjs\`.

GENERATED — run \`yarn icons\` to refresh.

${used
  .map(({ prefix, count, info }) => {
    const author = info.author?.url
      ? `[${info.author.name}](${info.author.url})`
      : (info.author?.name ?? "unknown");
    const licence = info.license?.url
      ? `[${info.license.title}](${info.license.url})`
      : (info.license?.title ?? "unknown");
    return `## ${info.name} (\`${prefix}\`)

- ${count} icon${count === 1 ? "" : "s"} used of ${info.total ?? "?"}
- Author: ${author}
- Licence: ${licence}${info.license?.spdx ? ` (\`${info.license.spdx}\`)` : ""}`;
  })
  .join("\n\n")}
`;

writeFileSync(attributionFile, attribution);

const kb = (statSync(outFile).size / 1024).toFixed(1);
console.log(`\n${total} icons -> ${relative(root, outFile)} (${kb} KB)`);
console.log(`credits    -> ${relative(root, attributionFile)}`);
